    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 20 }],
  });
  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 3, discountPercent: 50 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[0].qty, 8);
  assert.equal(r2.value.lines[0].discountPercent, 20);
});

test('removeLine removes a line from a draft invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(r1.ok, true);

  const r2 = removeLine(r1.value, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine reports LINE_NOT_FOUND for non-existent SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(removeLine(r1.value, 'NOPE'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if removing the last line', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(removeLine(r1.value, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const original = r1.value;
  const originalLineCount = original.lines.length;

  removeLine(original, 'DES-HOUR');

  assert.equal(original.lines.length, originalLineCount);
});

test('issueInvoice sets number and changes status to issued', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r1.ok, true);

  const r2 = issueInvoice(r1.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0001');
  assert.equal(r2.value.status, 'issued');
  assert.equal(r2.value.customerId, 'C-003');
  assert.equal(r2.value.issueDate, '2026-10-07');
});

test('issueInvoice uses existing numbers to find next', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r1.ok, true);

  const existing = ['INV-2026-0001', 'INV-2026-0002', 'INV-2026-0003'];
  const r2 = issueInvoice(r1.value, existing);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0004');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(issueInvoice(invoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const original = r1.value;
  const originalStatus = original.status;

  issueInvoice(original, []);

  assert.equal(original.status, originalStatus);
  assert.equal(original.number, undefined);
});

test('issueInvoice handles different years', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2027-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r1.ok, true);

  const existing = ['INV-2026-0050', 'INV-2027-0010'];
  const r2 = issueInvoice(r1.value, existing);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2027-0011');
});

